   const text=actual.toString('utf8'),a=text.indexOf('// ── Section 8:'),b=text.indexOf('// ── Section 9:',a);
   const outside=a>=0&&b>a&&hash(text.slice(a,b))===SPEC.smoke_section_after;
   throw Object.assign(new assert.AssertionError({message:outside?'unrecognized smoke changes outside Section8: #376 owner-recovery exact scope':'unrecognized smoke changes: independent Section8 after: #376 owner-recovery exact scope'}),{parallelismSmokeDrift:true});
