 try{validateOwn({artifacts,readRaw,value:ownerRecoveryLayerValue});}
 catch(error){if(error.parallelismSmokeDrift)throw error;if(inheritedError)throw inheritedError;throw error;}
 if(inheritedError)throw inheritedError;
